!function(e){function t(t){for(var i,n,o=t[0],m=t[1],c=t[2],s=0,g=[];s<o.length;s++)n=o[s],Object.prototype.hasOwnProperty.call(a,n)&&a[n]&&g.push(a[n][0]),a[n]=0;for(i in m)Object.prototype.hasOwnProperty.call(m,i)&&(e[i]=m[i]);for(d&&d(t);g.length;)g.shift()();return p.push.apply(p,c||[]),r()}function r(){for(var e,t=0;t<p.length;t++){for(var r,n=p[t],o=!0,m=1;m<n.length;m++)r=n[m],0!==a[r]&&(o=!1);o&&(p.splice(t--,1),e=i(i.s=n[0]))}return e}function i(t){if(n[t])return n[t].exports;var r=n[t]={i:t,l:!1,exports:{}};return e[t].call(r.exports,r,r.exports,i),r.l=!0,r.exports}var n={},a={101:0},p=[];i.m=e,i.c=n,i.d=function(e,t,r){i.o(e,t)||Object.defineProperty(e,t,{enumerable:!0,get:r})},i.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},i.t=function(e,t){if(1&t&&(e=i(e)),8&t)return e;if(4&t&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(i.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&t&&"string"!=typeof e)for(var n in e)i.d(r,n,function(t){return e[t]}.bind(null,n));return r},i.n=function(e){var t=e&&e.__esModule?function(){return e.default}:function(){return e};return i.d(t,"a",t),t},i.o=function(e,t){return Object.prototype.hasOwnProperty.call(e,t)},i.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=t,o=o.slice();for(var c=0;c<o.length;c++)t(o[c]);var d=m;p.push([28,0]),r()}({28:function(e,t,r){"use strict";r.r(t);var i=r(0);Object(i.a)("de","army",r(29),r(1))},29:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"坦克","link":"de_army#de_army_tank"}],"model":"Ⅵ号虎式（虎Ⅰ）坦克","description":"<h6>综述：</h6><p>虎式坦克于1942年7月开始定型生产（此前已经过多年的研发），至1944年8月共生产了1300多辆，定名为Pz.Kpfw Ⅵ号”虎”式（虎Ⅰ）坦克。虎Ⅰ坦克有2种正式型号，分别为“E”型和“H”型。虎Ⅰ坦克是一种重型坦克，车身和车体上部采用一体式焊接；虎Ⅰ坦克的装甲防护十分强大，其车体正面装甲为100，炮塔正面装甲110mm，侧面和背面装甲也有80mm厚，敌方火炮几乎无法将其击穿。虎Ⅰ坦克装备了88mm Kwk36 L/56火炮和二挺MG34机枪，其88mm火炮(原是一种防空高射炮,在北非战役中转作反坦克炮用，战绩十分突出，受到希特勒的极度欣赏。其威力强大，敌方坦克基本上难以抵挡其一击。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{image}}imgs/de/army/de_army_tankvi_11.jpg{{caption}}<p>考虑到坦克过重，不少桥梁会承受不了，故早期生产的虎式Ⅰ型坦克（近500辆）在车体后部装有一支排气管（见上图H型），坦克本身也作了水密防护，由此可在水下潜行，最大深度可达4m。但后期生产的坦克都取消了（见下图E型），以后虎式Ⅰ型坦克只能涉水2m。</p><p>注意：早期型的前灯是装在前车体上面（上图），而后期型则是把前灯安装在前车体的正面（下图）。</p>{{image}}imgs/de/army/de_army_tankvi_12.jpg","description":"<h6>Ⅵ号”虎”式（虎Ⅰ）坦克（Sd.Kfz.181 Pz.Kpfw Ⅵ Ausf.H TigerⅠ）</h6><p>Ⅵ号”虎”式（虎Ⅰ）坦克在1942年7月开始生产，曾采用了各种命名，包括“Aust.H”、“Aust.E”等，但实际上并没有明确作出区分，由于在生产的过程中不断改进，很多资料都是以其改进的情况分初期型（1943年前生产）和后期型（也有资料分初、中、晚三期）。</p><p>以下为Ⅵ号 ”虎” 式（虎Ⅰ）E型坦克的数据：车长：8.45m, 车宽：3.7m, 车高：2.93m, 车重：57t; 乘员5人； 发动机650（700）匹马力，车速：38km/h, 最大行程：220km; 主要武器：一门88mm KwK36 L/56火炮，二挺7.92mm MG34机枪；装甲百度：100mm。</p><p>早期生产的虎式Ⅰ型大部分都分配给国防军的501、502和503重型装甲营；随着中、后期产量的增加，陆续又分配给了504-510等多个重装营。</p><p>外形特点：1.悬挂系统中负重轮是交迭式，外层是4个大直径的钢轮。2.炮塔装备的是88mm火炮，其炮身与Ⅴ号坦克的75mm坦克炮不相同。3. 炮塔属小型炮塔，外形较为低矮。</p>","caption":""}],"part2title":"战场上的Ⅵ号虎式（虎Ⅰ）坦克","part2description":"<p>虎Ⅰ坦克从1942年8月首次出现在列宁格勒战场上，它就显示了其威力，四辆虎Ⅰ坦克受命增援被苏军24辆T-34坦克围攻的第96步兵师，在双方坦克对抗中，有12辆T-34坦克被虎Ⅰ坦克击毁，令苏军其余坦克撒走。以后无论是在东线或西线战场上，它都成为了德军装甲兵的中流砥柱。在虎Ⅰ坦克的乘员中，出现了不少王牌坦克手（其中最著名的是党卫军装甲部队的“魏特曼”）。虎Ⅰ坦克的弱点是机动性差，发动机损坏率较高，面部装甲也相对较弱，故此苏军和盟军坦克常常利用它的弱点，相遇时实行机动作战，绕到它的背后进行攻击。</p>","part2content":[{"image":"imgs/de/army/de_army_tankvi_21.jpg","description":"1942年，首次参战的虎Ⅰ坦克在俄罗斯的列宁格勒进行战斗，图中一辆苏军T—34坦克被虎Ⅰ坦克击毁。","caption":""},{"image":"imgs/de/army/de_army_tankvi_22.jpg","description":"1943年春，哈尔科夫战役后期，一辆在战场上疾行的大德意志装甲掷弹兵师虎Ⅰ坦克。","caption":""},{"image":"imgs/de/army/de_army_tankvi_23.jpg","description":"哈尔科夫战役中，正在前往战场的虎Ⅰ型坦克。注意：图中的背景是哈尔科夫教堂。","caption":""},{"image":"imgs/de/army/de_army_tankvi_24.jpg","description":"1943年6月，在苏联库尔斯克战役中一辆隶属505重装营的虎ⅠH型坦克，坦克兵正在对坦克进行检修。","caption":""},{"image":"imgs/de/army/de_army_tankvi_25.jpg","description":"1943年7月，在参加库尔斯克战斗后，一辆隶属武装党卫军帝国师第二装甲团8连的虎ⅠH型坦克编队行进。","caption":""},{"image":"imgs/de/army/de_army_tankvi_26.jpg","description":"一辆行进中属于德军第501重装营的虎Ⅰ坦克。","caption":""},{"image":"imgs/de/army/de_army_tankvi_27.jpg","description":"在苏联雪地中抛锚的一辆虎Ⅰ坦克，因为车重和动力问题，坦克机械经常出故障，一直对德军装甲部队的行进和战斗都有很大影响。","caption":""},{"image":"imgs/de/army/de_army_tankvi_28.jpg","description":"1943年5月，出现在法国地区的德军第502重装营第2连一辆虎Ⅰ坦克。图中坦克被涂成暗黄色，没有任何标志，站在士兵中前方的军官是一位上尉（左臂佩带一盾形标识）。","caption":""},{"image":"imgs/de/army/de_army_tankvi_29.jpg","description":"1944年6月在诺曼第的波卡基村，党卫军101重战车营的一辆虎Ⅰ坦克被盟军飞机炸毁后的情况。当时该车和几辆虎式坦克突入该村，但很快就受到盟军飞机的空袭，损失惨重。","caption":""},{"image":"imgs/de/army/de_army_tankvi_30.jpg","description":"1944年6月在诺曼第战场上，一辆由党卫军101重战车营1连3排指挥官Walter Hahn指挥的虎Ⅰ.E型坦克。","caption":""}]}')}});